#include <iostream>
using namespace std;

int jar[1000];
int main() {
    int n = 0, d = 0;
    cin >> n >> d;
    for (int i = 0; i < n; i++)
        jar[i] = 0;
    for (int i = 1; i <= d; i++) {
        int a = 0;
        cin >> a;
        jar[a] += i;
    }
    cout << jar[0];
    for (int i = 1; i < n; i++)
        cout << " " << jar[i];
    cout << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;
    for (int i = 0; i < n; i++) {
        char str[11];
        cin >> str;
        char max = '0';
        for (int i = 0; str[i] != '\0'; i++)
            if (str[i] > max)
                max = str[i];
        cout << (max <= '1') << " " << (max <= '7') << " " << (max <= '9') << " " << (max <= 'F') << endl;
    }
    return 0;
}
